#include <mach/mach.h>
#include <mach/mach_vm.h>
#include <stdio.h>
int main(void) {
    for (int region=0;region<2;region++) {
        unsigned attempts=0; int mapped=0;
        for (mach_vm_address_t requested=0x100000000;requested<0x1000000000;requested+=0x1000000) {
            mach_vm_address_t address=requested; attempts++;
            kern_return_t kr=mach_vm_map(mach_task_self(),&address,region?0x40000000:0x44000000,0,VM_FLAGS_FIXED,MEMORY_OBJECT_NULL,0,FALSE,VM_PROT_NONE,VM_PROT_ALL,VM_INHERIT_DEFAULT);
            if(kr==KERN_SUCCESS) {printf("region=%d address=%llx attempts=%u\n",region,address,attempts);mapped=1;break;}
        }
        if (!mapped) printf("region=%d unavailable attempts=%u\n",region,attempts);
    }
}
